# theme-switch [<name>|toggle|next]
#   <name>   switch to that theme
#   toggle   switch to the first theme of the other kind (day <-> night)
#   next     cycle through all themes
#   (none)   the theme scheduled for the current time
#
# Theme data and the schedule are generated by Nix into ~/.config/desktop/.
# Each app gets its active config symlink repointed at the theme's variant and
# a reload nudge; Quickshell watches the copied theme.json; night themes start
# the blue-light filter, day themes stop it.

config_dir="$HOME/.config"
themes_dir="$config_dir/desktop/themes"
schedule_file="$config_dir/desktop/schedule.json"
state_dir="$HOME/.local/state/desktop"

theme_names() {
  find "$themes_dir" -maxdepth 1 -name '*.json' -printf '%f\n' | sed 's/\.json$//' | sort
}

theme_kind() {
  jq -r '.mode // "day"' "$themes_dir/$1.json" 2>/dev/null || echo day
}

current_theme() {
  cat "$state_dir/theme" 2>/dev/null || true
}

scheduled_theme() {
  jq -r --arg now "$(date +%H:%M)" '
    (map(select(.time <= $now)) | last // empty | .theme)
    // (last | .theme)
  ' "$schedule_file"
}

usage() {
  echo "usage: theme-switch [<name>|toggle|next]" >&2
  echo "themes:" >&2
  theme_names | sed 's/^/  /' >&2
  exit 1
}

case "${1:-}" in
  toggle)
    current_kind=$(theme_kind "$(current_theme)")
    other_kind=night
    [ "$current_kind" = night ] && other_kind=day
    theme=""
    while read -r name; do
      if [ "$(theme_kind "$name")" = "$other_kind" ]; then
        theme="$name"
        break
      fi
    done < <(jq -r '.[].theme' "$schedule_file"; theme_names)
    ;;
  next)
    current=$(current_theme)
    theme=$(theme_names | awk -v cur="$current" 'found { print; exit } $0 == cur { found = 1 }')
    [ -n "$theme" ] || theme=$(theme_names | head -n1)
    ;;
  "")
    theme=$(scheduled_theme)
    ;;
  -h | --help)
    usage
    ;;
  *)
    theme="$1"
    ;;
esac

if [ -z "${theme:-}" ] || [ ! -f "$themes_dir/$theme.json" ]; then
  usage
fi

link() {
  [ -e "$1" ] && ln -sfn "$1" "$2"
  return 0
}

link "$config_dir/ghostty/config-$theme" "$config_dir/ghostty/config"
link "$config_dir/kitty/kitty-$theme.conf" "$config_dir/kitty/kitty.conf"
link "$config_dir/hypr/colors-$theme.lua" "$config_dir/hypr/colors.lua"
link "$config_dir/helix/themes/$theme.toml" "$config_dir/helix/themes/current.toml"
link "$config_dir/yazi/theme-$theme.toml" "$config_dir/yazi/theme.toml"
link "$config_dir/lazygit/config-$theme.yml" "$config_dir/lazygit/config.yml"

mkdir -p "$state_dir"
printf '%s\n' "$theme" > "$state_dir/theme.tmp"
mv -f "$state_dir/theme.tmp" "$state_dir/theme"
# A real copy (not a symlink) so Quickshell's file watch fires; install sets
# the mode instead of inheriting the read-only store mode.
install -m 644 "$themes_dir/$theme.json" "$state_dir/theme.json.tmp"
mv -f "$state_dir/theme.json.tmp" "$state_dir/theme.json"

# Reload signals: ghostty SIGUSR2, kitty and helix SIGUSR1. yazi and lazygit
# pick the new symlink up on their next launch.
pkill -USR2 -x ghostty 2>/dev/null || true
pkill -USR1 -x kitty 2>/dev/null || true
pkill -USR1 -x hx 2>/dev/null || true

# Live border colors (colors.lua above covers `hyprctl reload`).
field() {
  jq -r --arg k "$1" '.[$k] // "" | ltrimstr("#")' "$state_dir/theme.json"
}
active1=$(field borderActive1)
active2=$(field borderActive2)
inactive=$(field borderInactive)
hyprctl eval "hl.config({ general = { col = { active_border = { colors = { \"rgba(${active1}ee)\", \"rgba(${active2}ee)\" }, angle = 45 }, inactive_border = \"rgba(${inactive}aa)\" } } })" >/dev/null 2>&1 || true

# --no-block: this also runs from theme-init.service, which swaybg is ordered
# after.
if render-wallpaper "$state_dir/theme.json"; then
  systemctl --user --no-block restart swaybg.service 2>/dev/null || true
fi

# sunset-night carries a time-based warmth ramp: on entry, jump straight to
# wherever the ramp currently reads.
if [ "$theme" = sunset-night ]; then
  theme-warmth-ramp target > "$state_dir/bluelight-temp.tmp"
  mv -f "$state_dir/bluelight-temp.tmp" "$state_dir/bluelight-temp"
  if systemctl --user --quiet is-active hyprsunset.service; then
    hyprctl hyprsunset temperature "$(cat "$state_dir/bluelight-temp")" >/dev/null 2>&1 || true
  fi
fi

if [ "$(theme_kind "$theme")" = night ]; then
  systemctl --user start hyprsunset.service 2>/dev/null || true
else
  systemctl --user stop hyprsunset.service 2>/dev/null || true
fi

greeter-sync >/dev/null 2>&1 || true
